const html: string = "<div>\n        <p>\n          <span>1. &#160; негіздері</span>\n        </p>\n        <p>\n          <span>1.1. Бәс тігулер тек 21 жастан асқан адамдардан қабылданады.\n            Егер Клиенттің юрисдикциясының заңнамасы жоғарырақ белгілесе\n            Құмар ойындарға қатысудың ең төменгі жасы келесідей:\n            жоғары жас. Тіркеу, салым салу немесе жасы кіші адамның ставкасы\n            21 жаста (немесе юрисдикцияда заңмен талап етілген жасқа толмаған).\n            Клиент) Ережелерді өрескел бұзу болып табылады: Компания жабуға құқылы\n            шот, ставкалардан бас тарту және қайтарусыз қаражатты ұстау.&#160;</span>\n        </p>\n        <p>\n          <span>\n            1.2. Бәс тігулер ережелермен келісетін адамдардан ғана қабылданады,\n            одан әрі букмекерлік компания (Imba.bet) құрды. Кез келген мөлшерлеме\n            клиенттің осы ережелерді білетіндігін растау болып табылады\n            Мен олармен келісемін. Әкімшілік жарамсыз деп тануға құқылы\n            осы Ережелерді бұза отырып орналастырылған ставкалар. Әкімшілік олай емес\n            оның нақты қашан болғаны үшін жауапкершілік көтермейді\n            болғаны белгілі болды немесе кейіннен анықталды\n            Ережелерді бұза отырып жасалған.\n          </span>\n        </p>\n        <p>\n          <span>\n            1.3. Әкімшілік қабылдамайтын тұлғалардан ставкаларды қабылдамауға құқылы\n            осы ережелерді сақтау.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            1.4. Қабылдауға байланысты алаяқтық әрекеттер анықталған жағдайда\n            ставкалар немесе қаржылық операциялар, әкімшілік тоқтатуға құқылы\n            ставкаларды жарамсыз деп тану, жабу арқылы осындай әрекеттер\n            қаражат қалдығын қайтармай шоттарға және шағымдануға\n            құқық қорғау органдары алаяқтық жасағанына қатысты\n            әрекеттер.\n          </span>\n        </p>\n        <p>\n          <span>\n            1.5. Алда (голдан кейін) ставкалар анықталған жағдайда, шот\n            қайтарусыз бұғатталған.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            1.6. Клиенттен сенімді ставкаларға ставкалар болған жағдайда - шот\n            қайтарусыз блокталған.\n          </span>\n        </p>\n        <p>\n          <span>\n            1.7. Даулы мәселелер бойынша шағымдар 10 күн ішінде қабылданады\n            жазбаша өтініш негізінде іс-шара аяқталғаннан кейін.\n            Барлық даулы жағдайлар бойынша соңғы шешімді қабылдайды\n            administration.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            1.8. Осы Ережелер мен оларға түзетулер осы күннен бастап күшіне енеді\n            сайттағы жарияланымдар және барлық ставкалар мен әрекеттерге қолданылады,\n            жарияланған күнінен бастап, олардың білетініне қарамастан жасалған\n            клиенттерге ережелердің осы нұсқасының күшіне енуі немесе жоқтығы туралы. Барлығы\n            алдыңғы ережелер енді жарамсыз болып саналады.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            1.9.Компания ойын шотын жабу құқығын өзіне қалдырады,\n            егер Компания ставкаларды және балансты жою\n            мыналар анықталды: а) бәс тігу кезінде бәс тігушілер\n            оқиғаның нәтижесі туралы ақпарат (бекітілген сәйкестік); б) Бәс тігушілер\n            матчтың тікелей қатысушысы (спортшылар, төрешілер,\n            жаттықтырушылар және т.б.) немесе онымен келісім бойынша әрекет ететін тұлға; в) бәс тігу\n            Концертте әрекет ететін Бетторлар тобы қорытындылады\n            (синдикат) Қоғам белгілеген шектен шығу мақсатында;\n            d) бір ставканың бірнеше ойын шоттары бар; e) Қатысушы\n            бәс тігуге арнайы бағдарламалық жасақтаманы пайдалану күдіктенеді\n            автоматтандыруға мүмкіндік беретін бағдарламалық немесе техникалық құралдар\n            бәс тігу процесі; f) кез келген жосықсыз\n            ақпарат алу немесе белгіленген шектеулерді айналып өту жолдары\n            компания бойынша; ж) ойынның ұпайы деп санауға негіз бар\n            бәс тігу немесе басқа да байланысты әрекеттер үшін пайдаланылмайды\n            ойындармен. Жоғарыда сипатталған жағдайларда Bettor шотының қалдығы\n            қайта есептеуге жатады және жеке қарастырылады.\n          </span>\n        </p>\n        <p>\n          <span>2. Депозитті толтыру және ұтыстар алу</span>\n        </p>\n        <p>\n          <span>\n            2.1. Ұтыс тігулер сызық негізінде қабылданады - алдағы оқиғалар тізімі\n            букмекерлік кеңсе ұсынған баға белгілеулерімен - коэффициенттер\n            жеңу. Баға ұсыныстары кез келген ставкадан кейін өзгеруі мүмкін, бірақ шарттар мен талаптар\n            бұрын қойылған ставкалар өзгеріссіз қалады. Ойыншыларға бәс тігуден бұрын\n            жолдағы барлық өзгерістерді табу керек.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.2. Бәс тігулер оларды серверге орналастырып, алғаннан кейін орналастырылды\n            сұрауы бойынша ойыншыдан ставканың қабылданғаны туралы хабарлама және купон нөмірі\n            ойыншылар 4.5 тармағына сәйкес жойылуға немесе түзетуге жатпайды\n            осы Ереженің күшін әкімшілік жоюы мүмкін. Үзіліс\n            қосылымдар немесе басқа байланыс ақаулары негіз болып табылмайды\n            бәс тігу серверде тіркелген болса, бәс тігуден бас тарту үшін. Тарифтер\n            ағымдағы шоттың қалдығынан аспайтын сомада ғана қабылданады\n            клиент. Бәс тігуді тіркегеннен кейін ставка сомасы есептен шығарылады\n            шоттар. Ұтыс тігулер есептеліп болғаннан кейін ұтыс сомасы клиенттің шотына түседі\n            .\n          </span>\n        </p>\n        <p>\n          <span>\n            2.3. Бәс тігулердің келесі түрлері ажыратылады: «жалғыз»,\n            &quot;экспресс&quot; және «жүйе». Жалғыз ставка -\n            Тек бір оқиғаның нәтижесін болжау қажет болатын ставка.\n            Кез келген оқиғаға жалғыз ставкалар қабылданады. Жекелей сында жеңіс\n            ставкалар ұтыс коэффициентіне көбейтілген ставка сомасына тең.\n            Экспресс - одан көп нәтижені болжау керек ставка\n            бір уақытта бір оқиға. Кем дегенде бір оқиға болса\n            экспресс ставка қате болжанса, бүкіл экспресс ставка жоғалған болып саналады. Б\n            экспресс кез келген спорт түрінің кез келген комбинациясын қамтуы мүмкін.\n            Экспресске тәуелді оқиғаларды қосуға болмайды: бірдей оқиға\n            экспресске бірнеше рет қатыса алмайды, байланыстыруға болмайды\n            экспресс-ставкада матчтың нәтижесі және оған қатысушы командаға ставкалар\n            сәйкестік (мысалы: келесі айналымға өту және т.б.). Егер экспресс болса\n            тәуелді оқиғалар болып шықты, содан кейін тек есептеу мақсатында\n            ең жоғары коэффициентке ие олардың бірі. Жеңіс коэффициенті\n            экспресс ставка барлығының ұтыс коэффициенттерін көбейту арқылы есептеледі\n            экспресске енгізілген оқиғалар. Жедел пойыздардағы ұтыстар сомаға тең\n            экспресс ставканың ұтыс коэффициентіне көбейтілген ставка. Коэффицент\n            ұтыстар шексіз. Жүйе – экспресс пойыздардың толық комбинациясы\n            оқиғалардың алдын ала белгіленген санынан берілген өлшем\n            (жүйедегі оқиғалардың ең көп саны - 16). Әрбір комбинация\n            жүйеде ол бөлек экспресс ретінде есептеледі.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.4. Ең төменгі мөлшерлемені әкімшілік белгілейді. Максималды\n            желідегі бір ставка үшін төлем 3 миллион рубльді, тікелей эфирде - 1 миллионды құрайды\n            рубль Басқа валютадағы ставкалар үшін максималды төлем анықталады\n            кеңсе бағамы бойынша қайта есептеледі. Ойындар мен ставкалардың кейбір санаттары үшін\n            максималды ұтыс үшін арнайы шектеулер белгіленуі мүмкін,\n            осы Қағидалардың тиісті бөлімдерінде көрсетілген.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.5. Әкімшілік ең жоғары мөлшерлемені шектеуге құқылы\n            жеке оқиғалар, сондай-ақ максималды шектеу немесе арттыру\n            себептерін ескертусіз немесе түсіндірместен нақты клиентке мөлшерлеме.\n            Әкімшілік нақты шектеуге немесе бас тартуға құқылы\n            ұсынылатын қызметтерге немесе онсыз қызметтерге қол жетімді клиенттер\n            хабарламалар мен себептерін түсіндіру.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.6. Ұтыс тігулер оқиға басталғанға дейін қабылданады. сәйкес жағдайда\n            қандай да бір себептермен өтінім нақты басталғаннан кейін орналастырылды\n            оқиғалар болса, мұндай ставка жарамсыз болып саналады. Ерекшелік\n            «Тікелей» оқиғаларға ставкаларды, яғни ставкаларды жасау\n            матчтың барысы. Мұндай ставкалар жасалған жағдайда жарамды болып саналады\n            матчтың соңына дейін.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.7. Әкімшілік бас тартуға құқылы\n            «Тікелей» ставка, егер Әкімшілік клиентке күдіктенсе\n            бәс тігу кезінде көрсетілген оқиғаның нәтижесі туралы ақпарат болған\n            мөлшерлемесі. Бұл ретте Әкімшілік оның себебін дәлелдеуге міндетті емес\n            мұндай күдіктер &#160; туындайды\n          </span>\n        </p>\n        <p>\n          <span>\n            2.8. Егер клиент «Live» ставкасын қою барысында\n            коэффициенттердің немесе ставкалардың параметрлерінің өзгеруімен келісілді (гандикап,\n            жалпы және т.б.), онда ставка оқиға ұпайы болса да қабылданады\n            бәс тігу тіркелген уақытқа қарай өзгерді.\n          </span>\n        </p>\n        <p>\n          <span>3.&#160; ставкасын есептеу ерекшеліктері</span>\n        </p>\n        <p>\n          <span>\n            3.1. Жолда көрсетілген оқиғаның басталу күні мен уақыты\n            ақпараттық сипатта болады. Қате көрсетілген күн, уақыт немесе\n            қосымша ақпарат (турнирдің мәртебесі немесе кезеңі, біріншінің ұпайы\n            матч және т.б.) бәс тігуден бас тартуға негіз болып табылмайды. Жағдайда\n            егер оқиға бастапқы жарияланғаннан ерте немесе кеш болса\n            күні, нәтиже жарамды болып саналады, ал ставкалар қарастырылады\n            оқиға басталғанға дейін жасалған болса жарамды. Жағдайда\n            бәс тігудің 3 немесе одан да көп күні басталмаған оқиғаны кейінге қалдыру\n            қайтып келеді. Егер басталмаған оқиға одан аз уақытқа кейінге шегерілсе\n            3 күн тарифтер күшінде қалады, бірақ әкімшілік қабылдауға құқылы\n            оқиғаның аяқталуын күтпестен ставкаларды қайтару туралы шешім, ол туралы\n            ойыншылар ресми нәтижелерде хабарланады. Егер NBA, NHL сәйкес келсе\n            MLB немесе NFL белгіленген күні өтпеді немесе аяқталмады\n            қоспағанда, ставкалар келесі күні дереу қайтарылады\n            оқиғаның күні дұрыс көрсетілмеген жағдайлар.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.2. Оқиғалар тізімінде бірінші орынды алаңдағы команда көрсетеді\n            матч өтіп жатыр. Команданың алаңында матч өткен жағдайда,\n            оқиғалар тізімінде екінші орында көрсетілген (командалардың матчтарынан басқа).\n            бір қала немесе облыс), осы матчқа ставка қайтарылады және бастап\n            экспресс пойыздары алынып тасталды. Матчты бейтарап алаңда өткізу олай емес\n            бәс тігулерді жою үшін негіз болып табылады. Тақырыпта көрсетілген болса\n            турнир өтетін орынға сәйкес жарыстар, жазуға рұқсат етіледі\n            спортшы немесе үй иелері бірінші емес. Бұл жағдайда ставкалар болмайды\n            қайтарылады.&#160;\n          </span>\n        </p>\n        <p>\n          <span>3.3. Үзілген оқиғалар: </span>\n        </p>\n        <p>\n          <span>\n            3.3.1. Оқиға орын алған болып саналады, егер ол үзілсе және\n            ережелермен реттелетін ойынның кем дегенде белгілі бір бөлігін ойнады\n            толық уақыт. Жалпы матчқа бәс тігу үшін бұл: футбол – 65 мин.\n            (егер матч форматы стандартты болмаса, ойынның 70 пайызы\n            уақыт); баскетбол – 35 мин. (NBA және басқа турнирлер үшін\n            48 минуттық матчтар) және 28 мин. 40 минуттық матчтары бар турнирлер үшін;\n            хоккей - 45 мин.; Бэнди - 60 мин.; Американдық футбол – 50\n            мин; бейсбол - 5 иннинг; басқа спорт түрлері - кемінде 70%\n            ойнау уақыты. Ерекшелік - тең ұпайлар жағдайлары\n            ережелер рұқсат етпейтін спорт түрлері бойынша матчтарды тоқтату сәті\n            ұтыс ойыны (баскетбол, бейсбол, американдық футбол және т.б.). Бұларда\n            Мұндай жағдайларда оқиға болған жоқ деп есептеледі. Оқиға танылса\n            сәтсіз аяқталса, «Өтуге» ставкалар қайтарылады. Оқиға болса\n            жарамды деп танылады, содан кейін «Өтуге» ставкалар сәйкес есептеледі\n            ойын тоқтатылған кездегі нақты есеп және тең болған жағдайда\n            шот-фактуралар - қайтару. Ең үлкен демеушілікпен өткізілетін іс-шаралар үшін\n            халықаралық ұйымдар (мысалы, ФИФА және футболдағы УЕФА), қашан\n            Оқиғаның уақыты туралы ақпарат қоғамдық доменде тез пайда болады.\n            ойынның аяқталуы (30 сағатқа дейін), әкімшіліктің шешімі бойынша барлық ставкаларды жасауға болады\n            соңғы нәтижеге сәйкес есептеледі. Бәс тігулер үшін\n            матчтың жекелеген бөліктері (баскетболда ширек, футболда тайм,\n            хоккейдегі кезеңдер және сол сияқты) егер олар үзілген болса,\n            онда кем дегенде 70% өткен болса, олар ойналған болып есептеледі\n            осы бөлікке арналған ережелермен реттелетін ойнау уақыты\n            сәйкестік. Ойынның өткен уақытын есептеу тек қана есепке алынады\n            толық минут ойнады және бөлшектерді дөңгелектеу.\n            Мәселен, кейбіреулердің 14-минутында хоккей матчы үзіліп қалды\n            кезең, ал 13 минут 20 секунд ойналды. Бұл жағдайда\n            13 толық минут ойналды, бұл 65%, яғни аз,\n            70%-дан астам. Сондықтан осы кезеңдегі ставкалар жойылуға жатады.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.2. Анықтамаға кірмейтін үзілген оқиға\n            орын алған оқиға, егер ол жарамсыз деп танылуы мүмкін\n            3 сағат ішінде ойнауды аяқтамады.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.3. Орындалмаған деп танылған үзілген оқиғалар үшін қайтарыңыз\n            Нәтижесі уақыт бойынша болатын ставкалардан басқа барлық ставкалар ставкаларға жатады\n            Оқиғаны тоқтату ерекше түрде анықталады (мысалы, 1-ші ұпайды кім алады\n            мақсат, картаны алады, жалпы «артық» болды және т.б.). үшін\n            үзілген оқиғалар ставкалардың сөзсіз қайтарылуына жатады\n            жартылардың салыстырмалы көрсеткіштері (кезеңдер және т.б.).\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.4 Орындалды деп танылған үзілген оқиғалар есептеледі\n            жалпы негізде. Үзілген матчқа (ойын, жарыс немесе\n            т.б.), кері санақ басталмаған (мысалы, 76-дан 90-ға дейінгі мақсат\n            мин, егер матч 70-минутта үзілсе) қайтарылады. Бәс тігулер\n            басталған, бірақ аяқталмаған оқиғалар (мысалы, мақсат болады\n            матч 70-минутта үзілсе, 61 минуттан 75 минутқа дейінгі аралық)\n            жарамды болып есептеледі.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.5 Кейбір спорт түрлері үшін қосымша мүмкіндіктер болуы мүмкін\n            ставкаларды есептеу, егер олар ережелердің тиісті тармақтарында көрсетілген болса.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.4. Аяқталған оқиғаның бастапқы нәтижесі кейінірек болса\n            қандай да бір себептермен жойылса, бас тарту есепке алынбайды және\n            тарифтер бастапқы (нақты) сәйкес төленеді.\n            нәтиже. Нәтижесі жарияланды\n            ресми хаттамаларға және басқа да ресми дереккөздерге негізделген\n            оқиға аяқталғаннан кейін дереу ақпарат. Жағдайда\n            ресми дереккөздерде нәтиженің болмауы, әкімшілік құқығы бар\n            баламалы ақпарат көздерін пайдалану, соның ішінде\n            матчтағы өз өкіліңізден ақпарат. Кезекте болса\n            Байқаудың атауы қайнар көзін анық көрсетеді (мысалы,\n            теледидарлық хабар), онда анықтау кезінде басымдыққа ие болады\n            нәтиже. Оқиға үзіліп, келесі күні ойнатылатын болса\n            басынан бастап, содан кейін есеп айырысу мақсатында бірінші матч үзілген болып саналады\n            оқиға және 3.3 тармағына сәйкес есептеледі\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5. Әкімшілік ставканы жарамсыз деп тануға құқылы\n            жағдайларда:\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.1 Ұтыс тігулерді қабылдау кезіндегі персонал қателері немесе бағдарламалық құралдың ақаулары\n            (коэффициенттердегі анық қателер, коэффициенттердің сәйкессіздігі\n            әртүрлі позициялар және т.б.)\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.2 Спорттық емес жекпе-жектің айқын белгілері болса. Жағдайда\n            Фонбеттегі матчтардың спорттық емес сипаты туралы күдік туындайды\n            немесе халықаралық ұйымдардың ескертуі бойынша EWS-FIFA,\n            Federbet және Теннистің тұтастығы бірлігі әкімшілігінің құқығы бар\n            бұрын күдікті ставка жасаған Клиенттің ставкаларын блоктау\n            халықаралық ұйымның қорытындысы және ставкаларды мойындау\n            спорттық емес мінез-құлық фактісі анықталған жағдайда жарамсыз болып табылады\n            күрес. Әкімшілік ойыншыларға дәлелдеме беруге міндетті емес\n            және қорытындылар.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.3 Ставкаларды қабылдауға байланысты алаяқтық әрекеттерді анықтау\n            немесе операциялар, жалған құжаттарды көрсету;\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.4 Басқа біреудің есептік жазбасынан ойнау фактісін немесе оқиғаны растау\n            сіздің жеке кабинетіңізді рұқсат етілмеген тұлғалардың пайдалануына күдік.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.5 Тексеру рәсімінен өтуден бас тарту, сондай-ақ болған жағдайда\n            қайта тіркеу фактісін растау (оның ішінде пайдалану\n            басқа адамдардың жеке деректері, құжаттары, соның ішінде. жарамсыз және\n            жалған).\n          </span>\n        </p>\n        <p>\n          <span>3.5.6 Осы ережелерді бұзған басқа жағдайларда.</span>\n        </p>\n        <p>\n          <span>\n            3.6. Егер бәс тігу жарамсыз деп танылса,\n            осы ставканы қайтару және егер ол экспресске немесе жүйеге енгізілген болса, онда\n            есептеу мақсатында 1 коэффициентімен есепке алынады.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.7. Барлық ағымдағы нәтижелер, ойын уақыты, басқа да қосымша\n            сайтта көрсетілген ақпарат тек қана қызмет етеді\n            анықтамалық ақпарат. Әкімшілік бұл ақпаратты қамтамасыз етуге тырысады\n            дәл болды, бірақ ставкалардың салдарына жауапты емес,\n            осы мәліметтер негізінде жасалған. Клиентке кеңес беріледі\n            ставкаларды есептеудің дұрыстығын тексеру, соның ішінде тірі ставкалар,\n            ресми ақпарат көздерін пайдаланыңыз (ресми веб-сайттар\n            спорттық іс-шараларды ұйымдастырушылар).\n          </span>\n        </p>\n        <p>\n          <span>\n            3.8. Бір уақыттағы ставкалар және айналып өтуге мүмкіндік беретін ставкалар\n            бар максималды ставка немесе бір және сол үшін төлем сомалары\n            адамдар тобынан (ойыншылар синдикаты және т.б.) бірдей нәтижеге жол берілмейді. Жоқ\n            Бір комбинацияға қайталанатын ставкаларды қоюға рұқсат етіледі\n            жалпы әлеуетті төлем асқан жағдайда нәтижелер\n            максимум. Әкімшілік мұндай тарифтерді жариялауға құқылы\n            жарамсыз.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.9. Есептің немесе басқа сәйкестік параметрлерінің кез келген өзгерісі\n            ресми төрешінің шешімі (мысалы, офсайдқа байланысты голдың қабылданбауы,\n            бейнені қараудан, теннис нүктесін жоюдан немесе қайта қараудан кейін,\n            волейбол және т.б.) немесе қатысушылардың өзара келісімі (мысалы,\n            алаңнан қуылғаннан кейін бірдей күшпен ойнау және т.б.) себеп емес\n            ставкалардан бас тарту үшін.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.10. Прецедентсіз даулы жағдайларда, финал\n            Шешімді букмекерлік кеңсе одан әрі қабылдайды (Imba.bet).\n          </span>\n        </p>\n        <p>\n          <span>4. &#160; ставкаларының негізгі түрлері</span>\n        </p>\n        <p>\n          <span>\n            4.1. Нақты нәтижеге ставкалар. Онсыз матчтарға бәс тігуге болады\n            гандикапты ескере отырып, егер сәйкес коэффициенттер көрсетілсе (бірінші\n            позициялар – бірінші команданы жеңгені үшін («1»), екінші үшін\n            позиция - ұтыс үшін коэффициент «Х», үшінші позицияда -\n            екінші команданы жеңу коэффициенті («2»). Бұнда\n            Бұл жағдайда ставканың нәтижесі матчтың нақты нәтижесі болып табылады. Сондай-ақ\n            1-ші команда жеңілмейтініне бәс тігуге болады\n            (&quot;1Х&quot;), 2-ші команда ұтылмайды (&quot;Х2&quot;) немесе жоқ.\n            ұтыс ойыны болады (&quot;12&quot;).\n          </span>\n        </p>\n        <p>\n          <span>\n            4.2. Гандикапты ескере отырып, матчтағы әрбір команданың жеңісіне ставкалар\n            (андикап). Гандикапты букмекерлік кеңсе анықтайды және болуы мүмкін\n            оң, теріс немесе нөлге тең. Анықтау үшін\n            қай команда соққан нақты голдарға бәс тігу нәтижесі\n            бәс тігу жасалады, ол алынып тасталады (гендикап теріс болса) немесе\n            таңдалған команда үшін гандикап қосылады (егер гандикап оң болса)\n            (екінші команда үшін гандикап есепке алынбайды). Егер кейін\n            Егер матчтың нәтижесі таңдалған команданың пайдасына болса, онда\n            бәс жеңді деп саналады. Тең болған жағдайда – ставка\n            қайтарады. Мысалы, егер бірінші пәрмен орнатылған болса\n            теріс гандикап «-1», және матч аяқталды: а) есеппен\n            0:0, ұтылған ставка; б) 1:0 есебімен ставка қайтарылады; в) бірге\n            есеп 2:0, бәс жеңді. A, егер оң гандикап орнатылса\n            &quot;+0,5&quot; және матч аяқталды а) 0:1 есебімен, бәс тігу\n            жоғалған; б) 0:0 немесе 1:0 есебімен бәс жеңеді.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.3. Азиялық гандикап. Гандикапты қосқанда жеңіске немесе тоталға ставка\n            (гандикап), еселік 0,25 (бірақ 0,5 еселік емес). Бұл ставка\n            сомасының жартысы мөлшерінде екі ставка ретінде есептеледі, с\n            бірдей коэффициенттер және &quot;әдеттегінің ең жақын мәндерімен\n            үшін\" және \"тұрақты қорытындылар\" (бүтін немесе 0,5 еселіктері).\n            Жолдағы мұндай оқиғалар «Азия» префиксімен белгіленеді. Жағдайда\n            азиялық гандикап ставкасы экспресске немесе жүйеге енгізілген, содан кейін\n            Бұл ставканы есептеу кезінде ұтыс коэффициенттері пайдаланылады, бұл\n            егер ол бір таңбалы санмен есептелсе, алынар еді. Екеуі де жеңсе\n            Жартылай ставкалар үшін есептеулерде ставка коэффициенті (K) ескеріледі.\n            Бір жарты ставка ұтып, екіншісі ұтылған болса, есептеу\n            (К+1)/2 коэффициенті қабылданады. Бір жартысы ставка жасаса\n            жоғалды, бірақ басқа шығындар бойынша, экспресс пойыздарда коэффициент есептеледі\n            0,5. Егер жарты ставканың екеуі де жоғалса, онда бүкіл ставка қарастырылады\n            жоғалған.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.4. Голдардың, ұпайлардың, бұрыштамалардың, еркін соққылардың жалпы санына ставкалар,\n            карталар және кеңсе белгілеген басқа да іс-шаралар (&quot;Толығырақ -\n            Аз.\" Жоғарыда аталған оқиғалардың саны келесідей анықталады\n            жалпы мән «жалпы» деп аталады және оны кеңсе анықтайды. Жағдайда\n            жалпыға жетеді, ставка қайтарылады.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.5. Жарыста жеңіске жетуге немесе келесі кезеңге өтуге ставкалар\n            турнирлер. Қатысушы қандай да бір себептермен конкурсқа жарияланған болса\n            өйткені мен жарысты бастай алмадым, бәс тігулер осы қатысушыға\n            қайтаруға жатады. Екі немесе одан да көп қатысушылар бөліссе\n            жарыста жеңіске жету, олардың әрқайсысының ұтысы төленеді\n            формула бойынша есептелген ұтыс коэффициентіне негізделген\n            K=(Kish-1)/N+1, мұндағы Киш – бір қатысушыға шаққандағы бастапқы коэффициент,\n            N – конкурс жеңімпаздарының саны.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.6. Белгілі бір матч есебі мен уақыт матчына ставкалар. Пішіннің жылдамдығымен\n            &quot;уақыт сәйкестігі&quot; біріншісінің нәтижесін бір уақытта болжау керек\n            жартысы және бүкіл матч. Осы нәтижелерді көрсету үшін қатарда\n            Бастапқы әріптер қолданылады: P - жеңіс, N - тең, ал 1-ші\n            1-ші таймның нәтижесі орындалады, ал матч екінші орында. Нәтиже 2\n            жартылай уақыт бұл ставканы есептеу үшін маңызды емес. Мысалы, сәйкестік болса\n            1:1 есебімен аяқталды, ал бірінші тайм 1:0, содан кейін нәтиже жеңіске жетеді\n            P1N.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.7. Тур немесе ойын күні статистикасына ставкалар. Жағдайда\n            тур жарамсыз деп танылады (4.3-тармақтың критерийлеріне сәйкес) немесе жойылды (б.\n            4.1) тармағының критерийлері, кем дегенде бір матч, содан кейін тур статистикасына ставкалар\n            нәтижесі бір мәнді ставкаларды қоспағанда, қайтаруға жатады\n            анықталады (мысалы, 0:0 тең ойын болады ма, барлық командалар гол соғады ма және т.б.).\n            Букмекерлік кеңсе ставкаларды қайтару туралы шешім қабылдауға құқылы\n            турдың немесе ойын күнінің статистикасы, егер сенімді болса\n            тур басталғанға дейін матчтардың бірін тоқтату туралы ақпарат, ол туралы ойыншылар\n            ресми нәтижелерде хабарланады. Көрсеткіштерді есептеу үшін\n            матчты аяқтамаған ойыншыға теннис матчтарының ойын күні (\n            кез келген себеппен) барлық қалған жиынтықтар мен ойындарда есептеледі\n            жеңілу. Үй иелері – жолда көрсетілген командалар немесе ойыншылар\n            бірінші орында.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.8. Голдардың немесе ұпайлардың жұп немесе тақ жалпы санына ставкалар\n            сәйкестік. Коэффициенттер сызықта көрсетілген. Есеп 0:0 – жұп.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.9. Жеке өнімділікке немесе ойыншыларды салыстыруға ставкалар\n            (қатысушылар). Егер ойыншы алаңға кірмесе (қатыспаса), онда\n            Оның қатысуымен өткен іс-шараларға ставкалар қайтарылады. Қатысушылар үшін,\n            оқиғаны аяқтамағандар бойынша көрсеткіштер есептеледі\n            жою (алып тастау) кезіндегі нақты нәтиже және мақсаттар үшін\n            есептеу, мұндай қатысушыларға финалда соңғы орын тағайындалады\n            хаттама. «Хет-трик болады ма» деген ставкалар қарастырылады\n            ойыншы үш немесе одан да көп гол соққанда жеңді. Тарифтер\" болады\n            дубль бар ма? егер ойыншы екі немесе одан да көп ұпай жинаса, жеңіске жеткен болып саналады\n            мақсат. Ойыншының өнімділігіне, ойыншының өзі соққан голдарына ставкалар бойынша\n            оның көрсеткіштерінде қақпалар есепке алынбайды. қатысты тарифтерде\n            командалық нәтиже, команданың автоголға соққан голдары,\n            қарсыласының голы ретінде есептеледі. бойынша ставкаларды есептеу ерекшеліктері\n            Ойыншының теннис өнері абзацта көрсетілген.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.10. Ойыннан тыс спорт түрлерінде (шаңғы, биатлон, жеңіл атлетика және\n            т.б.) салыстыруда «Кім ұзын» егер қатысушы (эстафета үшін)\n            - команда) бастады, бірақ аяқтамады, содан кейін оған бәс тігу\n            олар басқа қатысушымен салыстырғанда жеңіледі. Екі қатысушы да кетсе\n            қашықтықтан немесе қатысушылардың біреуі бастамады - ставкалар қайтарылады.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.11. Жартылардың, кезеңдердің, ширектердің және т.б. нәтижелеріне ставкалар\n            егер оқиға жарамсыз деп танылса, бірақ бірінші жартыжылдық (кезең және\n            т.б.) аяқталды, содан кейін бірінші таймға ставкалар әдеттегідей есептеледі\n            жалпы оқиғаға ставкалар қайтарылса да тапсырыс.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.12. Осы немесе басқа оқиға болатын уақытқа ставкалар,\n            мысалы, 1-ші голдың уақыты, 1-ші картаның уақыты, алға шығу уақыты\n            командалардың бірі және т.б. реттік минутты болжау ұсынылады, бойынша\n            қандай оқиға орын алады. Мұндай тарифтерді есептеудің нақты уақыты\n            секундтарды есепке алмай анықталады. Мысалы, 1-ші голдың уақыты, егер\n            бірінші гол матч басталғалы 00 минут 10 секунд өткенде соғылды – «1-ші\n            минут», 04мин10сек – «5-минут», 04мин59сек – «5-минут»,\n            05мин00сек – «6-минут».\n          </span>\n        </p>\n        <p>\n          <span>\n            4.13. Пайызбен көрсетілген көрсеткіштерге ставкалар (алғашқы қызмет көрсету %,\n            допты иелену % және т.б.) Есептеу үшін көрсеткіштің мәні алынады\n            ресми сайт, арифметика ережелеріне сәйкес бүтін санға дейін дөңгелектенеді.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.14. Бір көрсеткіштің (p1) санына ставкалар\n            басқа индикатордың басталуының алдында (p2). Мысалы\n            &quot;бірінші голға дейін нысанаға бағытталған соққылар саны&quot;,\n            &laquo;бірінші карта алдындағы тәртіп бұзушылықтар саны&quot; т.б. нысанаға ату\n            гол соғылған немесе карточка берілген фол болып саналады.\n            Егер мақсаттар немесе карталар болмаса, нәтиже жалпы болып табылады\n            индикаторлар саны p1 (яғни нысанаға атудың жалпы саны немесе\n            бастар).\n          </span>\n        </p>\n        <p>\n          <span>5. Матч кезінде ставкаларды қабылдау (тірі ставкалар)</span>\n        </p>\n        <p>\n          <span>\n            5.1. Тікелей ставкалар негізгі және қосымша нәтижелерге қабылданады.\n            Жалғыз тірі ставкаларды қоюға немесе оларды біреуіне біріктіруге болады\n            экспресс\n          </span>\n        </p>\n        <p>\n          <span>\n            5.2. Ставка серверде тіркелгеннен кейін және қабылданған болып саналады\n            онлайн растау беру. Қабылданған тарифті өзгерту мүмкін емес.\n            тарауында көрсетілген мән-жайлар туындаған жағдайда «Негізгі\n            бәс тігулерді қабылдау ережелері» тармағында, коэфициенттермен тірі ставканы есептеуге болады\n            «1».\n          </span>\n        </p>\n        <p>\n          <span>\n            5.3. The bookmaker is not responsible for any inaccuracies in\n            current results of matches on which live bets are accepted.\n            Clients should also use other independent sources\n            ақпарат.\n          </span>\n        </p>\n        <p>\n          <span>5.4. Тікелей ставкалар өңделмейді немесе жойылмайды.</span>\n        </p>\n        <p>\n          <span>\n            6. Матчтардың нәтижелері, олардың басталу күні мен уақыты, шешім қабылдау тәртібі\n            даулы мәселелер\n          </span>\n        </p>\n        <p>\n          <span>\n            6.1. Тарифтік есептеулер қате болғандықтан қайта қаралуы мүмкін\n            букмекерлік кеңсе ұсынған нәтиже. Ұтыс тігулерді есептеу кезінде\n            оқиғалардың нақты басталу уақыты есепке алынады, бұл\n            шамамен ресми құжаттар негізінде анықталады\n            спорттық жарыстарды өткізетін ұйымдар, ал егер олар болмаса\n            бекітілген құжаттар, содан кейін ресми веб-сайттарға негізделеді\n            спорт федерациялары, спорт клубтарының веб-сайттары және басқа көздер\n            спорттық ақпарат.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.2. Букмекерлік компания жауапты емес\n            күн мен уақыт пен оқиғалардың нақты басталуы арасындағы сәйкессіздік. Күні мен уақыты\n            Жолда көрсетілген оқиғалардың басталуы индикативті болып табылады.\n            Ставкаларды есептеу кезінде оқиғаның нақты басталу уақыты ескеріледі,\n            ресми құжаттар негізінде анықталады\n            байқауды өткізетін ұйым.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.3. Букмекерлік кеңсе кез келген қателер үшін жауапты емес\n            чемпионаттардың атаулары және матчтардың ұзақтығы (спорт\n            оқиғалар). Жолда және тікелей эфирде көрсетілген деректер\n            индикативті сипатта. Клиенттер басқаларды пайдалануы керек\n            туралы мәліметтерді нақтылау үшін тәуелсіз ақпарат көздері\n            спорттық іс-шара. Оқиғаның нәтижесіне қатысты шағымдар қабылданады\n            ресми тұлғалар болған жағдайда іс-шара аяқталғаннан кейін 10 күн ішінде\n            өткізетін ұйым берген іс-шараның нәтижесі туралы құжаттар\n            бәсеке.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.4. Оқиға басталғаннан кейін қойылған ставкалар есептеледі\n            «1» коэффициенттері (тікелей ставкаларды қоспағанда); жедел пойыздарда\n            Мұндай ставкалар үшін коэффициент «1»-ге тең деп есептеледі.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.5. Клиент оқиғаға бәс тіккен болса, оның нәтижесі ол\n            белгілі болды, мұндай мөлшерлеме жойылуға жатады. Бұл жағдайда шешім\n            букмекерлік компания арнайы жабылғаннан кейін қабылданады\n            тергеулер. Мұндай тарифке қатысты барлық әрекеттер уақытша\n            уақытша тоқтатылды.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.6. Егер қатысушы оқиға басталғанға дейін күресуден бас тартса, онда барлығы\n            осы қатысушыға ставкалар жарамсыз болады.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.7. Егер қатысушы қандай да бір себептермен (жарақат, бас тарту және т.б.)\n            жарыс барысында жойылады, содан кейін барлық ставкалар басталғанға дейін қойылады\n            ол қатысқан конкурстың соңғы кезеңі немесе кезеңі,\n            жарамды болып саналады және басқа ставкалар жарамсыз болып табылады.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.8. Қатысушы, команда мүшесі (футболшы, хоккейші, баскетболшы\n            т.б.) матчқа қатыспаған, ұтыс ставкалары бойынша ұтыс коэффициенті\n            егер басқаша көрсетілмесе, ол «1-ге» тең деп есептеледі.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.9. Егер теннис матчында бас тарту (дисквалификация) бұрын орын алса\n            матчтың басталуымен ставкалар бойынша ұтыс коэффициенттері тең деп есептеледі\n            Қатысушының жарыстағы нәтижесіне ставкаларды қоспағанда, «1». Егер\n            теннис матчы үзілген, сол күні аяқталмаған және кейінге қалдырылған, ставкалар\n            ол турнирдің соңына дейін күшінде қалады\n            матч матч аяқталғанға дейін немесе бас тарту орын алғанша ойналды\n            қатысушылардың бірі.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.10. Егер іс-шарада (матч, жарыс немесе жекпе-жек) бір\n            қатысушылардың жұбы (командалар, спортшылар), содан кейін жұптың құрамы\n            өзгерсе, сол оқиғаға жасалған барлық ставкалар жарамсыз болады.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.11. Командалық жарыстарда біреуін немесе бірнешеуін ауыстыру кезінде\n            кез келген команданың қатысушылары кез келген себеппен, жалпы нәтижеге ставкалар\n            сәйкестіктер жарамды болып қалады.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.12. Жұптық матчтарда, егер жұптардың құрамы көрсетілген болса, кем дегенде ауыстыру кезінде\n            қатысушылардың біреуі болса, ставкалар бойынша ұтыс коэффициенті тең болады\n            «1». Егер құрам белгіленбесе, ставкалар сақталады.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.13. Жарыстарда «хост» және ұғымдары\n            «қонақтар», оқиға өткен жағдайда: бейтарап алаңға – ставкалар\n            күшті болып қалу; қарсылас команданың алаңында – ставкалар жарамды болып қалады.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.14. Егер «хосттар» және «қонақтар» ұғымдары іс-шараға қолданылмаса\n            (мысалы, жеке және жұптық спортта), содан кейін ауысқанда\n            оқиғаның орны, оған барлық ставкалар жарамды болып қалады. Командалар\n            NBA, NHL, AHL, CHL, OHL, WHL, East Coast хоккей лигасы\n            Солтүстік Американы тікелей реттілікпен орналастыруға болады\n            (үй иелері - қонақтар) және керісінше. Кері орналасу жағдайында\n            Ұтыс тігулер бойынша қайтарулар жоқ.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.15. Клубтық жолдастық турнирлердің жолдастық кездесулерінде\n            Оқиға орны өзгерген кезде оған барлық ставкалар өзгеріссіз қалады\n            күш.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.16. Спорт немесе бөлек болмайтын жағдайлар\n            бәс тігулерді қабылдау және есептеу ерекшеліктерінің сипаттамасы Жалпыға бағынады\n            ережелер.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.17. Прецеденті жоқ даулы жағдайларда финал\n            шешімді букмекерлік компания қабылдайды.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.18. Әртүрлі көздерден алынған деректер сәйкес келмеген жағдайда\n            ақпарат (күні, уақыты, нәтижесі, топ атауы)\n            Букмекерлік компания ұтыстарды төлеуді толыққанға дейін тоқтатады\n            мұндай ақпараттың шынайылығын тексеру. Нәтиже болса\n            аяқталған іс-шара ресми веб-сайтта ұсынылған,\n            телехабар деректерінен ерекшеленеді, Компания кетеді\n            теледидар деректері негізінде есептеулер жүргізу құқығын өзіне қалдырады\n            таратылымдар.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.19. Коэффицентті шығару бағдарламасында қате анықталса және\n            компанияның бұл қатені мойындауы, осыған салынған барлық ставкалар\n            оқиғалар ұтты болып саналады және ставкалар онымен төленеді\n            ұтыс коэффициенті «1»-ге тең.\n          </span>\n        </p>\n        <p>\n          <span>7. Тараптар &#160;</span>\n        </p>\n        <p>\n          <span>\n            7.1. Келісімнің барлық тармақтары, соның ішінде «біз», «біз»,\n            «біздің» немесе «Компания» клиентпен жұмыс істейтін компанияны білдіреді\n            жоғарыдағы 1-тармаққа сәйкес шарт жасайды.\n          </span>\n        </p>\n        <p>\n          <span>8. Шарттардың өзгеруі</span>\n        </p>\n        <p>\n          <span>\n            8.1. Бірқатар себептер бойынша, атап айтқанда: коммерциялық, заңды, сондай-ақ\n            тұтынушыларға қызмет көрсетуге байланысты себептерге құқығымыз бар\n            Келісімге кез келген өзгерістер енгізу. Келісімнің ағымдағы тармақтары және\n            олардың күшіне ену мерзімі веб-сайтта көрсетілген. Клиент жеке\n            ағымдағы Келісіммен танысу үшін жауапкершілік. У\n            Компания веб-сайттың жұмысына өзгерістер енгізуге құқылы\n            кез келген уақытта және Клиенттерді алдын ала хабардар етпестен.\n          </span>\n        </p>\n        <p>\n          <span>\n            8.2. Шарттың өзгертілген тармақтарымен келіспеген жағдайда, Клиент\n            веб-сайтты пайдалануды тоқтату керек. Әрі қарай пайдалану\n            Шарттың өзгертілген тармақтары күшіне енгеннен кейін веб-сайт,\n            қарамастан оның толық қабылданғаны ретінде қарастырылады\n            Клиент тиісті хабарлама алды ма немесе білді ме\n            жаңартылған Келісімдегі өзгерістер.\n          </span>\n        </p>\n        <p>\n          <span>9. Талап қою құқығы</span>\n        </p>\n        <p>\n          <span>\n            9.1. 21 жасқа толмаған адамдар (бұдан әрі -\n            Рұқсат етілген жас), бұл заңдылық үшін міндетті\n            белгілі бір юрисдикцияның заңдарына сәйкес құмар ойындарға қатысу\n            (21 жастан асқан болса) Веб-сайтты пайдалануға тыйым салынады.\n            Веб-сайтты рұқсат етілген жасқа толмаған адамдардың пайдалануы\n            Келісімді тікелей бұзу болып табылады. Осыған байланысты бізде\n            растай алатын құжаттарды кез келген уақытта сұрауға құқылы\n            Клиенттің жасы мен тұлғасы. Клиент бас тартылуы мүмкін\n            қызметтерді көрсету, оның аккаунты уақытша тоқтатылуы мүмкін\n            немесе тоқтатылды, ставкалар мен ұтыстар жарамсыз және қалған қаражат\n            қайтарусыз ұсталады, егер олар біздің өтінішіміз бойынша ұсынылмаса\n            Клиенттің жасы сәйкес келетіндігінің дәлелі\n            Қабылдауға болады немесе Клиенттің қол жеткізбегені анықталса\n            Жас шегі.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            9.2. Кейбір юрисдикцияларда онлайн құмар ойындар заңсыз болып табылады.\n            Шартты қабылдау арқылы Клиент Компанияның мүмкін емес екенін түсінеді\n            қатысты кепілдіктер немесе заңгерлік кеңес беру\n            юрисдикция аумағында веб-сайтты пайдаланудың заңдылығы, в\n            Клиент қайда орналасқан. Біз қызметтер деп айта алмаймыз\n            Веб-сайт Клиенттің юрисдикциясының заңдарын бұзбайды. Клиент пайдаланады\n            өз өтініші бойынша веб-сайттың қызметтерін толық көлемде алуға міндеттенеді\n            жауапкершілік, барлық ықтимал тәуекелдерді жақсы білу.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.3. Біз Клиентке қызметтерді іздемейміз және ұсынбаймыз\n            өз құзыретіндегі заңдарды бұзу. Келісімді қабылдау арқылы,\n            Клиент Веб-сайтты пайдалануды растайды және кепілдік береді\n            өз аумағында қолданыстағы заңдар мен ережелерге сәйкес келеді\n            юрисдикция. Біз заңсыз пайдалану үшін жауапты емеспіз\n            веб-сайттың қызметтері.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.4. Заңды себептерге байланысты біз келесі клиенттерді қабылдамаймыз\n            елдер:\n          </span>\n        </p>\n        <p>\n          <span>\n            9.4.1. Абсолютті шектеу. АҚШ-тан келген клиенттер қабылданбайды\n            Канада, Ұлыбритания, Испания, Латвия, Литва, Нидерланды,\n            Франция, Италия, Швейцария, Албания, Барбадос, Пәкістан, Сирия,\n            Оңтүстік Судан, Кайман аралдары, Гаити, Ямайка, Солтүстік Корея,\n            Мальта және Панама. аумақта тұратын немесе тұратын тұлғалар\n            бұл елдерде шот ашуға немесе қаражат салуға рұқсат етілмейді\n            Веб-сайттағы қаражат. Юрисдикциялардың тізімі өзгеруі мүмкін және олар\n            Компания алдын ала ескертусіз шығара алады\n            Клиенттер. Сіз шот ашпайтыныңызға келісесіз немесе\n            бірінің аумағында болған кезде оған ақша аудару\n            жоғарыда аталған юрисдикциялардан.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.4.2. Қара тізім. 9.4.1 тармағына қосымша, барлық NetEnt ойындары\n            келесі елдерде тыйым салынған: Ауғанстан, Албания, Алжир, Ангола,\n            Австралия, Камбоджа, Эквадор, Гайана, Гонконг, Индонезия, Иран,\n            Ирак, Израиль, Кувейт, Лаос, Мьянма, Намибия, Никарагуа, Солтүстік\n            Корея, Пәкістан, Панама, Папуа-Жаңа Гвинея, Филиппин, Сингапур,\n            Оңтүстік Корея, Судан, Сирия, Тайвань, Уганда, Йемен, Зимбабве,\n            Бельгия, Болгария, Дания, Эстония, Латвия, Литва, Чехия, Мексика,\n            Португалия, Румыния.\n          </span>\n        </p>\n        <p>\n          <span>9.4.3. Брендтік ойындарға арналған шектеулер.&#160;</span>\n        </p>\n        <p>\n          <span>\n            9.4.3.1. Games Guns &amp; Раушан, Джими Хендрикс және Моторхед емес\n            келесі елдерде қызмет етті: Ауғанстан, Албания, Алжир,\n            Ангола, Камбоджа, Эквадор, Гайана, Гонконг, Индонезия, Иран, Ирак,\n            Кувейт, Лаос, Мьянма, Намибия, Никарагуа, Солтүстік Корея, Пәкістан,\n            Панама, Папуа-Жаңа Гвинея, Филиппин, Сингапур, Оңтүстік Корея, Судан,\n            Сирия, Тайвань, Уганда, Йемен, Зимбабве, Бельгия, Болгария, Канада,\n            Дания, Эстония, Франция, Италия, Латвия, Литва, Мексика, Португалия,\n            Румыния, Испания, Америка Құрама Штаттары, Ұлыбритания,\n            Австралия, Әзірбайжан, Қытай, Үндістан, Малайзия, Катар, Ресей,\n            Тайланд, Тунис, Түркия және Украина.&#160;\n          </span>\n        </p>\n        <p>\n          <span>9.4.3.2. Ойындар </span>Әмбебап құбыжықтар (Франкенштейн, қалыңдық\n          Франкенштейн, Дракула, «Елестің қарғысы», «Қара жаратылыс».\n          Лагун және көрінбейтін адам\n          <span>\n            ), ТЕКСЕРЕК келесі елдерде қызмет көрсетіледі: Андорра,\n            Армения, Әзірбайжан, Беларусь, Босния және Герцеговина, Бразилия,\n            Грузия, Исландия, Лихтенштейн, Молдова, Монако, Черногория,\n            Норвегия, Ресей, Сан-Марино, Сербия, Швейцария, Украина, Хорватия,\n            Македония, Түркия, Австрия, Болгария, Кипр, Финляндия, Германия,\n            Греция, Венгрия, Ирландия, Люксембург, Мальта, Нидерланды, Перу,\n            Польша, Словакия, Словения және Швеция.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            9.4.4. Біріктірілген джекпот шектеулері. Біріктірілген джекпоттар\n            оларға қолдау көрсетілмейді және келесі елдерде қол жетімді болмауы мүмкін:\n            Австралия, Әзірбайжан, Қытай, Дания, Үндістан, Израиль, Италия,\n            Жапония, Малайзия, Катар, Ресей, Испания, Таиланд, Тунис, Түркия,\n            Біріккен Араб Әмірліктері және Украина.\n          </span>\n        </p>\n        <p>\n          <span>9.5. Бәс тігулер қабылданбайды:</span>\n        </p>\n        <p>\n          <span>\n            9.5.1. іс-шараларға қатысушылар болып табылатын адамдардан\n            бәс тігушілер (спортшылар, жаттықтырушылар, төрешілер, клуб иелері немесе лауазымды тұлғалар).\n            және іс-шараның нәтижесіне ықпал ету мүмкіндігі бар басқа адамдар), сондай-ақ\n            олардың атынан әрекет ететін тұлғалардан; мүдделерін білдіретін тұлғалардан\n            басқа букмекерлік компаниялар;\n          </span>\n        </p>\n        <p>\n          <span>\n            9.5.2. букмекерлік кеңсемен келісімге қатысуы басқа тұлғалардан\n            компанияға қолданыстағы заңнамамен тыйым салынады.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.6. Осы Шарттың 9.5-тармағын бұзғаны үшін жауапкершілік\n            бәс тігушілер көтереді. Осы Келісімді бұзған жағдайда,\n            букмекерлік компания төлемнен бас тартуға құқылы\n            кез келген ұтыстар немесе депозитке салынған сомаларды қайтару, сондай-ақ\n            кез келген ұтыс тігулерді жою. Букмекерлік компания көтермейді\n            жауапкершілік&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            Клиенттің кіріп жатқанын қашан білгені туралы\n            жоғарыда аталған адамдар санаттарының біріне жатады. Бұл дегеніміз\n            букмекерлік компания бұл шараларды кез келген уақытта қабылдауға құқылы\n            клиенттің бірі екені белгілі болғаннан кейін уақыт өткен соң\n            көрсетілген тұлғалар.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.7. Егер бәс тігушілер қатысты алаяқтық жасаса\n            букмекерлік компания (көп есептік жазба, бағдарламалық құралды пайдалану\n            ставкаларды автоматтандыру, арбитраждық жағдайларда ойнау, егер ойын болса\n            шот ставкаларды, теріс пайдалану үшін пайдаланылмайды\n            адалдық бағдарламалары және т.б.), содан кейін букмекерлік компания кетеді\n            бас тарту арқылы мұндай алаяқтық әрекеттерді тоқтату құқығын өзіне қалдырады\n            бәс тігу және ставкаға қатысушының ойын шотын жабу.\n          </span>\n        </p>\n        <p>\n          <span>10. &#160; шотын ашу</span>\n        </p>\n        <p>\n          <span>\n            10.1. Барлық маңызды қызметтерге қол жеткізу үшін\n            Веб-сайт, сізге тіркелгі ашу керек. Бұл үшін Клиент мүмкін\n            «1 шертуде» тіркеліңіз немесе мекенжайыңызды көрсетіңіз\n            электрондық поштаны жіберіңіз және құпия сөзді ойлап табыңыз, ол кейінірек болады\n            ойын профиліне кіру үшін пайдаланылады, сонымен қатар, қосымша\n            Қажетті жеке ақпарат: аты-жөні, телефон нөмірі және күні\n            туған.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            10.2. Тұтынушы нақты электрондық пошта мекенжайын көрсетуі керек\n            тіркеу процесі немесе «1 басу» тіркеу жағдайында өзгерту\n            нақты мекенжай.\n          </span>\n        </p>\n        <p>\n          <span>\n            10.3. Ақпараттың дұрыстығын растау үшін Компанияда\n            Клиенттің жеке басын растайтын құжаттарды талап ету құқығы. Егер\n            қандай да бір себептермен Клиент сұрағанын бермейді\n            жеке басын куәландыратын құжаттар, Қоғам тоқтата тұруға құқылы немесе\n            Клиенттің профилін олар қажет болғанша блоктаңыз\n            ақпарат.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            10.4. Клиент веб-сайтта тіркелу кезінде ол\n            өзі туралы толық және нақты мәліметтерді көрсеткен және болған жағдайда\n            онда кез келген өзгерістер орын алса, Клиент өзіне міндеттенеді\n            Оларды дереу профиліңізге қосыңыз. Орындамау немесе\n            бұл ережені елемеу қолданбаға әкелуі мүмкін\n            шектеулер, профильді тоқтата тұру немесе блоктау, сондай-ақ\n            төлемдерді жою.\n          </span>\n        </p>\n        <p>\n          <span>\n            10.5. Егер сізде сұрақтар немесе проблемалар болса\n            Веб-сайтта тіркелгеннен кейін Клиент қолдау қызметіне хабарласа алады\n            онлайн чат немесе қоңырау арқылы – 8 (800) 301-77-89\n            (тәулік бойы).\n          </span>\n        </p>\n        <p>\n          <span>\n            10.6. Әрбір Клиент веб-сайтта бір ғана есептік жазба аша алады.\n            Клиент ашқан басқа шоттар көшірме болып саналады. Бізде бар\n            мұндай шоттарды жабуға және жарамсыз деп тануға құқығы бар\n            қайталанатын шотты пайдалану арқылы жүзеге асырылатын барлық операциялар.\n          </span>\n        </p>\n        <p>\n          <span>\n            10.6.1. Клиенттерге жасалған барлық депозиттер мен ставкаларды қайтармаңыз\n            негізгі және резервтік шоттар; барлығының қайтарылуын талап етеді\n            ұтыстар, бонустар және пайдалану кезінде алынған ақшалай қаражат\n            қайталанатын тіркелгі. Клиент оларды бірінші рет қайтаруға міндетті\n            талап.&#160;\n          </span>\n        </p>\n        <p>\n          <span>11. Жеке басын тексеру. Заңдастыру&#160;</span>\n        </p>\n        <p>\n          <span>\n            11.1 Есіңізде болсын, аты мен туған күні,\n            Сіздің профиліңізде көрсетілген деректер сізге сәйкес келуі керек\n            шын аты.\n          </span>\n        </p>\n        <p>\n          <span>\n            11.2 Тіркелу кезінде сіздің профиліңізде көрсетілген аты болуы керек\n            несие картасындағы немесе басқа төлем профильдеріндегі атауды сәйкестендіріңіз,\n            ойынға/ойынға ақшаны толтыру немесе алу үшін пайдаланылады\n            account.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.3 Жеке басыңызды, мекенжайыңызды және/немесе төлеміңізді растау үшін\n            профиль (жеке тұлға) біз кез келген уақытта сұрай аламыз: &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.3.1. жеке басын куәландыратын құжат (оның ішінде, бірақ олармен шектелмей, көшірмелері\n            жарамды төлқұжат/идентификатор және/немесе пайдаланылған\n            төлем карталары),\n          </span>\n        </p>\n        <p>\n          <span>\n            11.3.2. мекенжайды растау, соның ішінде соңғысымен шектелмей\n            коммуналдық төлемдер (үш айдан аспайды\n            рецепт), &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.3.3 таңдалғанға қатысты шоттардың жай-күйі туралы банктен анықтама\n            төлем әдісі (үш айдан артық емес).\n          </span>\n        </p>\n        <p>\n          <span>\n            11.4 Егер сіз бізге осы құжаттарды бермесеңіз және/немесе біз бере алмасаңыз\n            ақылға қонымды уақыт ішінде жеке басыңызды растаңыз,\n            біз анықтаған, біз құқықты сақтаймыз;&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.4.1 Клиент профилін тексеруге дейін блоктау\n            сәтті аяқталады;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.4.2 транзакцияларыңыздың барлығын немесе кейбірін жарамсыз етеді\n            және профиліңізді қатырыңыз және/немесе профиліңізді жабыңыз немесе жабыңыз және\n            осы Келісімді бұзу.\n          </span>\n        </p>\n        <p>\n          <span>\n            11.5 Біз қауіпсіздікті тексеру құқығын өзімізде қалдырамыз\n            жеке басыңыз, жасыңыз туралы ақпаратты растау үшін кез келген уақытта\n            және сіз берген басқа тіркеу немесе төлем ақпараты\n            Қызметтерді пайдалануыңызды тексеру үшін (мысалы,\n            Тыйым салынған әрекеттерді болдырмау), сіздің осы талаптарды орындауыңыз\n            Жасалған қаржылық операцияларыңыз бойынша келісімдер мен чектер\n            Қызметтерді пайдалану шеңберінде бұның ықтимал бұзылуы үшін\n            Келісімдер.\n          </span>\n        </p>\n        <p>\n          <span>\n            11.6 Сіз букмекерлік кеңсеге кез келген сұрау салу құқығын бересіз\n            Сізге қатысты кез келген үшінші тарапқа пайдалану және ашу\n            оны тексеру мақсатында сіз туралы кез келген ақпарат.\n          </span>\n        </p>\n        <p>\n          <span>\n            11.7 Сіз біздің сұрауымыз бойынша кез келгенін беруге келісесіз\n            Аудит жүргізуге арналған қосымша ақпарат немесе құжаттар\n            қауіпсіздік.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.8 Бұл процедура міндетті талап болып табылады және келесі жылы орындалады\n            қолданыстағы құмар ойындар ережелеріне сәйкес және\n            ақшаны жылыстатуға қарсы күрес жөніндегі заң талаптары, соның ішінде\n            туралы Ұлттық ережеге сәйкес, атап айтқанда\n            стандартты емес транзакциялар және біздің ішкі ақпараттар туралы ақпарат беру\n            ақшаны жылыстатуға қарсы және алдын алу саясаты\n            терроризмді қаржыландыру.\n          </span>\n        </p>\n        <p>\n          <span>12. Пайдаланушы аты, құпия сөз және қауіпсіздік</span>\n        </p>\n        <p>\n          <span>\n            12.1. Веб-сайтта шот ашқаннан кейін Клиент оны сақтауға міндетті\n            пароль мен пайдаланушы аты құпия сақталады және жария етілмейді\n            үшінші тұлғаларға ақпарат. үшін қажетті деректер жоғалған жағдайда\n            тіркелгіге қол жеткізу, сіз оларды басу арқылы білуге немесе қалпына келтіруге болады\n            «Құпия сөзді қалпына келтіру» түймесін басыңыз.\n          </span>\n        </p>\n        <p>\n          <span>\n            12.2. Клиент парольдің сақталуына, сондай-ақ кез келген әрекеттерге жауапты\n            және оның шотымен жасалған операциялар. Сонымен қатар, Клиент көтереді\n            оның әрекеті нәтижесінде келтірілген барлық шығындар үшін жауапкершілік\n            үшінші тарап.\n          </span>\n        </p>\n        <p>\n          <span>\n            12.3. Қауіпсіздік бұзылған және рұқсатсыз кіру жағдайында\n            шотқа Клиент букмекерлік кеңсеге дереу хабарлауы керек\n            компания. Қажет болған жағдайда Клиент Компанияға ұсынуға міндетті\n            рұқсат етілмеген қол жеткізудің жарамдылығының дәлелі\n            болды. Букмекерлік компания келтірілген зиян үшін жауапты емес\n            қате немесе ұқыпсыз нәтижесінде Клиент алған\n            пайдаланушы аты мен құпия сөзді үшінші тараптың немесе үшін пайдалануы\n            тіркелгіге рұқсатсыз кіру.\n          </span>\n        </p>\n        <p>\n          <span>\n            13. Шотқа ақша қаражатын салу, орналастыру және алу\n          </span>\n        </p>\n        <p>\n          <span>\n            13.1. Веб-сайтта ставка жасау үшін Клиент міндетті түрде\n            шотыңызға белгілі бір ақша сомасын салыңыз.\n          </span>\n        </p>\n        <p>\n          <span>13.2. Клиент мыналарды растайды және міндеттейді:</span>\n        </p>\n        <p>\n          <span>\n            13.2.1. ойын шотына салынған қаражат жоқ\n            заңсыз немесе тыйым салынған жолмен алынған;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.2.2. Клиент аяқталған транзакциялардан бас тартпайды\n            болуы мүмкін жасалған төлемдерден бас тартады және күшін жояды\n            ақшаны үшінші тұлғаға қайтару және олардың құтылу себебі\n            заңды жауапкершілік.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.3. Біз үшінші тұлғалардан қаражат қабылдамаймыз: достар,\n            туыстары немесе серіктестері. Клиент ақшаны депозитке салуға міндетті\n            тек сіздің шотыңыздан, банк картасынан немесе жүйеңізден,\n            Клиенттің атына тіркелген. Егер фактілер анықталса\n            Бұл шартты бұзған жағдайда барлық ұтыстар тәркіленуі мүмкін.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.4. Ақшаны қайтару үшін банктік аударым сұралған жағдайда\n            қаражат олардың заңды иесіне беріледі, барлық шығындар мен комиссиялар төленеді\n            алушының есебінен.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.5. Біз қолма-қол төлемді қабылдамаймыз. Біз\n            электрондық төлемдер, соның ішінде кіріс төлемдері үшін пайдаланылуы мүмкін\n            Клиенттерге, әртүрлі ұйымдарға төлемдер мен төлемдер\n            электрондық төлем процессорлары немесе қаржы институттары. үшін\n            осы мекемелердің ережелері мен шарттарын қоспағанда\n            Шарттың талаптарына қайшы келсе, Клиент мұны толығымен қабылдайды\n            rules.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.6. Тұтынушы бас тартпауға, бас тартпауға немесе\n            шотын пайдалана отырып жүргізілген транзакцияларды жою. Оның үстіне, в\n            Осындай жағдайлардың әрқайсысында Клиент қайтаруға немесе өтеуге міндетті\n            Шығындарды қоса алғанда, компанияның орналастырылмаған қаражатының сомасы,\n            Клиенттердің депозиттерін жинау кезінде туындауы мүмкін.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.7. Компания Клиенттің есептік жазбасын блоктауға құқылы, сонымен қатар\n            төлемдерден бас тарту және егер бар болса, ұтыстарды қалпына келтіру\n            шот толтырылды деген күдік туды\n            алаяқтық жолмен. Тиісті органдарға хабарлауға құқығымыз бар\n            құзырлы органдар төлемдерді алаяқтық және заңсыз\n            әрекеттер. Инкассация қызметтерін пайдалануға құқығымыз бар\n            қайтару агенттіктері. Компания жауапты емес\n            қарамастан несие карталарын рұқсатсыз пайдалану\n            олардың ұрланғаны туралы хабарланды ма.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.8. Біз Клиент шотындағы оң балансты пайдалануға құқығымыз бар\n            Клиент өтеуге тиісті ақша сомасын қайтаруға\n            Компаниялар. Атап айтқанда, қайталанатын ставкалар немесе ставкалар жағдайында, сәйкес\n            10-тармақ («Алдасу, алдау, алаяқтық»\n            және қылмыстық әрекет) немесе 13-тармақ («Қателер және\n            кемшіліктер\")&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.9. Клиент ойын ойнау фактісін толық біледі және қабылдайды\n            шот банк шоты емес. Сондықтан, қатысты\n            оған сақтандыру, толықтыру, кепілдік беру әдістері және басқа әдістер қолданылмайды\n            депозиттерге кепілдік беру жүйесінен қорғау әдістері және т.б\n            сақтандыру жүйелері. Ойын шотындағы қаражат жоқ\n            пайыздар алынады.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.10. Клиент шоттан ақшаны алу туралы өтінішті қашан беруге құқылы\n            болған жағдайда:\n          </span>\n        </p>\n        <p>\n          <span>\n            13.10.1 Шотқа түскен барлық төлемдер тексерілді, бірде-бір емес\n            оның күші жойылмаған немесе жойылмаған;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.10.2 Тексеру шаралары дұрыс жүргізілді.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11. Шоттан ақшаны алу туралы өтінішті орындау кезінде міндетті түрде болуы керек\n            келесі тармақтар ескеріледі:\n          </span>\n        </p>\n        <p>\n          <span>13.11.1. ойын профилі толығымен толтырылуы керек;</span>\n        </p>\n        <p>\n          <span>\n            13.11.2. егер сұратылған алу операциясының нәтижесі жалпы сома болса\n            қаражатты алу 50 000 рубльден асады. немесе\n            кез келген басқа валютадағы баламалы сома, ол жүзеге асырылады\n            сәйкестендіру процедурасы. Мұны жүзеге асыру үшін Клиент міндетті\n            бізге құжаттың көшірмесін немесе цифрлық фотосуретін жіберіңіз,\n            Клиентті анықтау. Тіркелгіні толтыру кезінде\n            несие картасы, сіз екі жақтың суретінің көшірмесін жіберуіңіз керек\n            бұл карта. Алғашқы алты және\n            соңғы төрт сан, CVV2 кодын жасыруға болады;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11.3. компания шығындарды өтеу үшін комиссия алуға құқылы,\n            ойында пайдаланылмаған қаражатты алумен байланысты;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11.4. алу сомасы 5 000 рубльге дейін немесе оған балама сома\n            басқа валюта, клиенттің шотына 1-ден 60 минутқа дейін төленеді\n            техникалық ақауларды қоспағанда, өтінім берілген сәттен бастап\n            банктің немесе төлем жүйесінің тараптары;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11.5. алу сомасы 5000 рубльден немесе балама сомадан\n            бастап 5 күн ішінде клиенттің шотына төленетін басқа валюта\n            өтініш беру сәті;\n          </span>\n        </p>\n        <p>\n          <span>\n            11/13/6. 3 жұмыс күніне дейінгі басқа кідірістерге байланысты болуы мүмкін\n            банктен немесе басқа төлем жүйесінен;\n          </span>\n        </p>\n        <p>\n          <span>\n            11/13/7. ұтыстарды қайтарып алудың басқа жолдары бөлек талқыланады\n            Веб-сайт әкімшілігімен.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12. Компания ақша айырбастау қызметін көрсетпейді.\n            Біз осындай шоттарды жабуға құқығымыз бар және:\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12.1. алу шығындары көлемінде комиссияны ұстап қалу\n            ойынға қатыспаған қаражат;&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12.2. жүргізілген барлық операцияларды жарамсыз деп тану\n            негізгі және қайталанатын шоттарды пайдалану;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12.3. Клиенттерге негізгі және\n            қайталанатын тіркелгілер.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.13 Ақшаны алуды белсендіру үшін ойыншы қажет\n            әрбір жасалған депозиттің кемінде 100%-ын құрайтын ставкаларды орналастырыңыз\n            немесе әрбір салымның кем дегенде 100% пайдаланыңыз\n            платформамыздағы кез келген ойындарда (ойнаңыз, қолданыңыз).\n          </span>\n        </p>\n        <p>\n          <span>\n            13.14. Ұтыс сомасы 5 000 000 астам болса\n            (бес миллион рубль), букмекерлік компанияның резерві\n            есептелетін күнделікті алу шегін белгілеу құқығы\n            әр Клиент үшін жеке.\n          </span>\n        </p>\n        <p>\n          <span>14. Букмекерлік кеңсе қызметтерінің талаптары:</span>\n        </p>\n        <p>\n          <span>\n            14.1. Сіз барлық қызметтерді және/немесе тауарларды немесе басқаларды төлеуге келісесіз\n            Сіз веб-сайтта тапсырыс берген қосымша қызметтер, сондай-ақ барлығы\n            қосымша шығындар (қажет болған жағдайда), оның ішінде, бірақ жоқ\n            салықтардың, баждардың және т.б. барлық түрлерімен шектеледі. Сіз толық көтересіз\n            Барлық төлемдерді уақтылы төлеуге жауапкершілік. Провайдер\n            төлем қызметтері төлемнің белгіленген мерзімде жүзеге асырылуын ғана қамтамасыз етеді\n            Веб-сайт өлшемі және төлемге жауапты емес\n            Веб-сайтты пайдаланушы жоғарыда көрсетілген қосымша сомаларды. Кейін\n            «Төлем» түймесін басу арқылы төлем өңделген болып саналады,\n            және ол қайтарымсыз орындалады. «Төлем» түймесін басу арқылы сіз\n            төлемді қайтара алмайтыныңызға келісесіз немесе\n            оның күшін жоюды талап етеді. Сайтқа тапсырыс беру арқылы сіз растайсыз және\n            ешбір мемлекеттің заңдарын бұзбағаныңызды көрсетіңіз.\n            Сонымен қатар, осы ережелердің (және/немесе Шарттардың және\n            ережелері), сіз төлем картасының иесі ретінде растайсыз\n            ұсынылатын тауарларды және/немесе қызметтерді пайдалануға құқығы бар\n            Website.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            14.2. Веб-сайт ұсынысының қызметтерін пайдалансаңыз\n            ойын қызметтері сияқты арнайы қызметтерді ұсынасыз\n            қол жеткізгеніңізді немесе қол жеткізгеніңізді заңды түрде растау\n            заңды кәмелеттік жасқа толған\n            қызметтерді пайдалану үшін сіздің юрисдикцияңызда рұқсат етілген\n            веб-сайтымен қамтамасыз етілген.\n          </span>\n        </p>\n        <p>\n          <span>\n            14.3. Веб-сайттың қызметтерін пайдалануды бастау арқылы сіз міндеттенесіз\n            кез келген заңдарды сақтау үшін заңды жауапкершілік\n            осы қызмет пайдаланылатын елдерде және растаңыз\n            Төлем қызметінің провайдері ешқайсысы үшін жауапкершілік көтермейді\n            заңсыз немесе рұқсат етілмеген ұқсас бұзушылық. Келісемін\n            Веб-сайттың қызметтерін пайдалансаңыз, сіз мұны түсінесіз және қабылдайсыз\n            Төлемдеріңіздің кез келгенін өңдеуді төлем провайдері жүзеге асырады\n            қызметтерді көрсетеді және сатып алынған заттарды қайтаруға заңды құқығы жоқ.\n            қызметтерді және/немесе тауарларды немесе басқа төлемді тоқтату опцияларын. Егер сіз\n            келесі сатып алу үшін қызметті пайдалануды тоқтатқыңыз келеді\n            қызметтерді және/немесе тауарларды пайдалансаңыз, сіз қызметті пайдаланудан бас тарта аласыз\n            Веб-сайттағы жеке тіркелгі.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            14.4. Төлем қызметін жеткізуші жауапты емес\n            төлеміңізге қатысты деректерді өңдеуден бас тарту/қабілетсіздік\n            карта, не эмитент-банктен алынбауына байланысты бас тарту үшін\n            төлем картаңызды пайдаланып төлем жасауға рұқсат\n            карталар. Төлем қызметін жеткізуші жауапты емес\n            Сізге ұсынылатын кез келген қызметтің және/немесе өнімнің сапасы, көлемі, бағасы\n            немесе төлем картаңыз арқылы веб-сайтта сатып алған.\n            Веб-сайттың кез келген қызметтеріне және/немесе тауарларына ақы төлеу арқылы сіз, ең алдымен,\n            веб-сайтты пайдалану ережелерін сақтауға міндетті. Назар аударыңыз\n            төлем картасының иесі ретінде сіз ғана жауаптысыз\n            сіз тапсырыс берген кез келген қызметтің және/немесе өнімнің уақытылы төлемі үшін\n            веб-сайт арқылы және осыған байланысты барлық қосымша төлемдер үшін\n            шығындар/комиссиялар. Төлем қызметінің провайдері ғана\n            Веб-сайтта көрсетілген сомада төлемді орындаушы және оны көтермейді\n            кез келген бағаға, жалпы бағаларға және/немесе жалпыға жауапкершілік\n            сомалар.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            14.5. Егер келіспеушілігіңізге байланысты жағдай туындаса\n            жоғарыда аталған шарттармен және/немесе басқа себептермен сізден сұраймыз\n            төлемді уақтылы төлеуден бас тартуға және қажет болған жағдайда,\n            Веб-сайт әкімшісіне/қолдау қызметіне тікелей хабарласыңыз.\n          </span>\n        </p>\n        <p>\n          <span>\n            15. Сөз байласу, бұрмалау, алаяқтық және\n            қылмыстық әрекет&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.1. Компания Клиенттер тобына бәс тігуді ұсынбайды\n            бір IP мекенжайы немесе бір жергілікті желіден, сондай-ақ\n            алдын ала мақұлдау. Жоғарыдағы қадамдар болуы мүмкін\n            сөз байласу, алаяқтық, iске қосу әрекеттерi болып есептеледi\n            адасу.\n          </span>\n        </p>\n        <p>\n          <span>\n            15.2. Компания ешқандай жауапкершілік көтермейді\n            ол мұны қашан білді немесе кейінірек анықтады\n            бәс ережелерді бұзумен жасалды. Жабуға құқығымыз бар\n            ұқсас тіркелгілер және:&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.2.1. барлық транзакцияларды жарамсыз деп тану, қайтармау\n            Клиенттерге басқалармен келісім бойынша жасалған барлық депозиттер мен ставкалар\n            Клиенттер;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.2.2. барлық ұтыстарды, бонустарды және қолма-қол ақшаны қайтаруды талап ету\n            сөз байласу нәтижесінде алынған қаражат. Клиент қайтаруға міндетті\n            оларды бірінші сұрауымыз бойынша.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.3. Келесі әрекеттерге қатаң тыйым салынады\n            мұндай әрекеттер тікелей бұзушылық ретінде қарастырылады\n            Келісімдер: &#160;\n          </span>\n        </p>\n        <p>\n          <span>15.3.1. ақпаратты үшінші тарапқа беру;</span>\n        </p>\n        <p>\n          <span>\n            15.3.2. заңсыз әрекеттер: алаяқтық, қанау\n            зиянды бағдарламалар, боттар және бағдарламалық құрал қателері\n            Веб-сайт; &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.3.3. ұрланған заттарды пайдалану сияқты алаяқтық әрекеттер,\n            клондалған немесе басқа жолмен заңсыз алынған несие деректері\n            немесе шотты толтыру үшін дебеттік карта;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.3.4. қылмыстық әрекеттерге қатысу, ақшаны жылыстату және т.б\n            қатысуы мүмкін әрекеттер\n            қылмыстық жауапкершілік;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.4. Біз тоқтата тұруға, жоюға немесе алып тастауға құқылымыз\n            бонустық қорлармен байланысты төлемдер немесе ұтыстар, соның ішінде\n            егер біз Клиенттің қасақана екеніне күдіктенсек\n            оларға қиянат жасайды.\n          </span>\n        </p>\n        <p>\n          <span>\n            15.5. Компания рұқсат етілген және заңмен рұқсат етілген барлық нәрсені қабылдайды\n            алаяқтық қастандықтарды болдырмау және анықтау бойынша әрекеттер және олардың\n            тікелей қатысушылар, сондай-ақ міндетті түрде осы тұлғаларға қарсы\n            Тиісті шаралар қабылданатын болады. Біз апармаймыз\n            нәтижесінде Клиенттер алған шығындар мен залалдар үшін жауапкершілік\n            алаяқтық әрекеттер.\n          </span>\n        </p>\n        <p>\n          <span>\n            15.6. Клиенттер болса, бізге дереу хабарлауы керек\n            Кез келген Клиентте күдік туындайды\n            сөз байласып немесе алаяқтық әрекеттерді жасайды.\n            Веб-сайт арқылы қызметке хабарласу арқылы бізбен байланыса аласыз\n            онлайн чат немесе қоңырау шалу арқылы қолдау – 8 (800)\n            301-77-89 (24 сағат).&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.7. Біз алдын ала ескертусіз тыйым салуға құқылымыз\n            Клиенттер бұл жағдайда веб-сайтқа кіріп, тіркелгілерін блоктайды\n            егер олар алаяқтық әрекет жасады деп күдіктенсе. Мұндайда\n            Біз қайтару және өтемақы үшін жауапты емес жағдайларда\n            осындай Клиенттердің шоттарында бар қаражат. Сонымен қатар, сағат\n            заңсыздығы туралы құқық қорғау органдарына хабарлауға құқығымыз бар\n            әрекеттер. Клиенттер бізбен толық ынтымақтасуға міндетті\n            мұндай жағдайларды тергеу.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.8. Клиенттерге қызметтер мен бағдарламалық құралды пайдалануға тыйым салынады\n            кез келген алаяқтық, заңсыз әрекеттер жасау үшін веб-сайтты қамтамасыз ету\n            кез келген заңдарға сәйкес әрекеттер мен мәмілелер\n            арнайы юрисдикция. Егер факт анықталса немесе анықталса\n            Клиент мұндай әрекеттерді жасаса, Компания жасай алады\n            Клиенттің шотын тоқтата тұру немесе блоктау және қаражатты ұстау,\n            онда қол жетімді. Мұндай жағдайларда Клиенттердің ұсынуға құқығы жоқ\n            Компанияның кез келген шағымдары.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.9. атынан ойын қызметін жүзеге асыруға тыйым салынады\n            үшінші тұлғалар (ойын шотының номиналды иелері).\n          </span>\n        </p>\n        <p>\n          <span>\n            Ойын профилі дереу блоктауға жатады, егер\n            қызмет көрсету қызметкерінің ойын профилін тексеру процесі\n            қауіпсіздік тексеруден өтетін тұлғаның жоқ екені анықталады\n            спорттық ставкалар саласында жеткілікті білімі бар\n            оқиғалар.&#160;\n          </span>\n        </p>\n        <p>\n          <span>16. &#160; веб-сайтындағы басқа тыйым салынған әрекеттер</span>\n        </p>\n        <p>\n          <span>\n            16.1. Агрессивті немесе қолдануға тыйым салынады\n            қарым-қатынастың қорлау тәсілі, балағат сөздер, қорқытулар және\n            қызметкерлерге қарсы кез келген зорлық-зомбылық әрекеттерін қолдану және\n            Компанияның басқа клиенттері. Клиент осы тармақты орындамаған жағдайда\n            ережелерге сәйкес Компания осы Клиентпен байланысты тоқтатуға құқылы\n            немесе кіріс өтінімді қараусыз қалдырыңыз.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            16.2. Веб-сайтқа мүмкін болатын көлемде ақпаратты жүктеуге тыйым салынады\n            Веб-сайттың жұмысында бұзылулар тудыруы және кез келген басқа әрекеттерді орындау\n            ресурстың жұмысына әсер етуі мүмкін әрекеттер. Бұл жағдайда\n            бұл вирустар, зиянды бағдарламалар, жаппай жіберулер және\n            спам – жоғарыда аталғандардың барлығына қатаң тыйым салынады. Сонымен қатар, Клиенттер\n            жарияланған ақпаратты жоюға, өзгертуге немесе өңдеуге тыйым салынады\n            Website.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            16.3. Клиенттер веб-сайтты тек осы мақсатта пайдалана алады\n            ойын-сауық мақсатында. Толық немесе ішінара көшіруге тыйым салынады\n            Website.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            16.4. Клиенттер бұзуға бағытталған әрекеттерді жасамауға міндеттенеді\n            Веб-сайттың қауіпсіздік жүйелеріне заңсыз қол жеткізу\n            құпия деректер немесе DDoS шабуылдары. Клиенттерге қатысты,\n            осы ережені бұзды деген күдікке ілінеді\n            тиісті шаралар: Веб-сайтқа кіруге толық тыйым салу және\n            профильді блоктау. Сонымен қатар, хабарлауға құқығымыз бар\n            Client.&#160; заңсыз әрекеттері туралы жауапты органдар\n          </span>\n        </p>\n        <p>\n          <span>\n            16.5. Біз кез келген жоғалту немесе зақымдану үшін жауапты емеспіз\n            техникалық себептерге байланысты біздің Клиенттерімізге немесе үшінші тұлғаларға жүктеледі\n            вирустық шабуылдардан немесе басқа зиянды әрекеттерден туындаған сәтсіздіктер\n            веб-сайтқа бағытталған әрекеттер.\n          </span>\n        </p>\n        <p>\n          <span>\n            16.6. Бір Клиенттің профилін беруге және сатуға қатаң тыйым салынады\n            басқа.&#160;\n          </span>\n        </p>\n        <p>\n          <span>17. &#160; келісімін бұзу шарттары мен тәртібі</span>\n        </p>\n        <p>\n          <span>\n            17.1. Компания Клиенттің профилін (сонымен қатар оның атын) жоюға құқылы\n            және пароль) келесі жағдайларда алдын ала ескертусіз:\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.1. Компания қызметтерді көрсетуді тоқтату туралы шешім қабылдады\n            Клиенттердің барлығы немесе белгілі бір бөлігі;&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.2. Клиент профилі қандай да бір түрде бұрын жойылғанмен байланысты\n            профиль;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.3. Клиент профилі қазіргі уақытта блокталған профилімен байланысты\n            профиль, бұл жағдайда Компания профильді жабуға құқылы\n            байланыс түріне қарамастан және тіркелгі деректерін толығымен блоктайды\n            бұл профильдер. Шартта өзгеше көзделмесе,\n            Клиенттің профилінде орналасқан қаражат қайтарылады\n            оны белгілі бір мерзімде, өтінішті толтырғаннан кейін бірден және\n            Клиенттің Компанияға қарыз сомасын ұстап қалу;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.4. Клиент қылмыстық қастандыққа қатысуда немесе әрекет етуде\n            жүйені бұзу;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.5. Клиент бағдарламалық жасақтамаға кедергі жасайды\n            Веб-сайт немесе кез келген басқа әрекеттерді жүзеге асыру әрекеті;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.6. Клиент өзінің профилін мүмкін болатын мақсаттарда пайдаланады\n            кез келген заң бойынша заңсыз деп саналады\n            арнайы юрисдикция;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.7. Клиент веб-сайтта қорлайтын немесе ақпаратты жариялайды\n            қорлайтын сипаттағы.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.2. Компания Клиенттің профилін жабуға немесе одан бас тартуға құқылы\n            тиісті хабарламаны жіберу арқылы Шарттың әрекет ету мерзімі\n            байланыс ақпаратында көрсетілген электрондық пошта мекенжайы. Мұндай жағдайда\n            тармақта көрсетілген жағдайларды қоспағанда, біздің тарапымыздан әрекеттер\n            15 («Алдасу, алдау, алаяқтық және\n            Қылмыстық әрекет») және 22 («Шарттарды бұзу»).\n            Келісімге сәйкес, Компания шоттағы қаражатты қайтаруға міндетті\n            Клиент. Егер қандай да бір себептермен біз жасай алмасақ\n            Клиентке хабарласыңыз, қаражат уақытша аударылады\n            букмекерлік кеңсенің немесе қадағалау органының есебі.\n          </span>\n        </p>\n        <p>\n          <span>18. Веб-сайтқа енгізілген өзгерістер</span>\n        </p>\n        <p>\n          <span>\n            18.1. Біз кез келген уақытта өз қалауымыз бойынша,\n            Веб-сайтта ұсынылатын қызметтерге өзгерістер немесе толықтырулар енгізу\n            ресурсты қолдау және жаңарту мақсатында.\n          </span>\n        </p>\n        <p>\n          <span>19. Жүйелік қателер</span>\n        </p>\n        <p>\n          <span>\n            19.1. Ойын барысында веб-сайтта ақаулық орын алса,\n            Компания жағдайды мүмкіндігінше тезірек түзетуге тырысады. Бізде жоқ\n            Ақпараттық БАҚ-тағы мәселелерге біз жауаптымыз\n            жабдықты пайдалану нәтижесінде пайда болатын технологиялар,\n            Клиенттер веб-сайтқа кіру үшін, сондай-ақ қателер үшін пайдаланылады\n            Интернет-провайдерлердің жұмысы.\n          </span>\n        </p>\n        <p>\n          <span>20. Қателер мен кемшіліктер</span>\n        </p>\n        <p>\n          <span>\n            20.1. Компания кез келген ставкаларды шектеуге немесе жоюға құқылы.\n          </span>\n        </p>\n        <p>\n          <span>\n            20.2. Егер Клиент өзіне алған қаражатты пайдаланса\n            қате нәтижесінде есепке алу, ставкаларды қою және ойынға қатысу, біз\n            біз мұндай ставкаларды және олардан алынған кез келген ұтысты жарамсыз ете аламыз\n            көмек. Егер осындай тарифтер бойынша ақшалай төлем жасалса\n            қаражат болса, онда бұл сомалар Клиентке аударылған деп есептелуі керек\n            сенімгерлік басқару кезінде Клиент оларды біріншіден қайтаруға міндетті\n            біздің талап.\n          </span>\n        </p>\n        <p>\n          <span>\n            20.3. Компания мен қызмет жеткізушілері келтірілген зиян үшін жауапты емес\n            қателер нәтижесінде ұтыс жоғалтуды қоса алғанда\n            Клиент тарапынан немесе біздің тарапымыздан.\n          </span>\n        </p>\n        <p>\n          <span>\n            20.4. Компания, оның дистрибьюторлары, филиалдары, лицензиаттары, еншілес ұйымдары\n            кәсіпорындар, сондай-ақ қызметкерлер мен басшылар көтермейді\n            салдарынан туындаған кез келген шығын немесе залал үшін жауапкершілік\n            &#160; ұстап алу немесе дұрыс қолданбау\n          </span>\n        </p>\n        <p>\n          <span>Интернет арқылы берілетін ақпарат.&#160;</span>\n        </p>\n        <p>\n          <span>21. &#160; жауапкершілігімізді шектеу</span>\n        </p>\n        <p>\n          <span>\n            21.1. Клиент қызметтерді пайдалануды өз бетінше шешеді\n            Веб-сайт және кез келген әрекеттер мен олардың салдары салдары болып табылады\n            Клиенттің өз қалауы бойынша жеке таңдауы\n            қорқыныш пен тәуекел.\n          </span>\n        </p>\n        <p>\n          <span>\n            21.2. Веб-сайттың жұмысы тармақтарға сәйкес жүзеге асырылады\n            осы Келісімнің. Компания ешқандай қосымша ұсынбайды\n            веб-сайтқа және қызметтерге қатысты кепілдіктер немесе өкілдіктер\n            ол бойынша ұсынылады және осылайша оның жауапкершілігін алып тастайды (б\n            заңда көзделген мөлшерде) барлық көзделгендерге қатысты\n            кепілдіктер.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            21.3. Біз құқық бұзушылықтар, абайсыздықтар үшін жауапты емеспіз,\n            бұл жағдайда болжауға болмайтын шығындар мен залалдар\n            сәт.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            21.4. Компания ресурстардың мазмұнына жауапты емес,\n            веб-сайты арқылы қол жеткізуге болады.\n          </span>\n        </p>\n        <p>\n          <span>22. Шарттарды бұзу</span>\n        </p>\n        <p>\n          <span>\n            22.1. Клиент шығындарды толығымен өтеуге келіседі\n            Қоғамның, оның серіктестерінің, қызметкерлерінің және мүдделерін қорғау және қорғау\n            директорларды кез келген талаптардан, жауапкершіліктен, шығындардан, шығындардан және\n            байланысты туындайтын шығыстар:&#160;\n          </span>\n        </p>\n        <p>\n          <span>22.1.1. Клиенттің Шарт талаптарын бұзуы;</span>\n        </p>\n        <p>\n          <span>22.1.2. Клиенттің заңдар мен үшінші тұлғалардың құқықтарын бұзуы;</span>\n        </p>\n        <p>\n          <span>\n            22.1.3. кез келген басқа тұлғаның веб-сайт қызметтеріне қол жеткізуі\n            Клиенттің сәйкестендіру деректерін оның рұқсатымен немесе рұқсатынсыз пайдалану\n            ол, немесе;\n          </span>\n        </p>\n        <p>\n          <span>22.1.4. осы жолмен алынған ұтыстарды иелену.</span>\n        </p>\n        <p>\n          <span>\n            22.2. Егер Клиент Шарт талаптарын бұзса, бізде\n            дұрыс:\n          </span>\n        </p>\n        <p>\n          <span>\n            22.2.1. Клиентке өз әрекеттерімен оны бұзатындығы туралы хабарлау\n            Шарттың талаптарын және дереу бұзуды талап етеді\n            тыйым салынған әрекеттер;\n          </span>\n        </p>\n        <p>\n          <span>22.2.2. Клиенттің есептік жазбасын тоқтата тұру;&#160;</span>\n        </p>\n        <p>\n          <span>\n            22.2.3. алдын ала ескертусіз Клиенттің есептік жазбасын бұғаттау;\n          </span>\n        </p>\n        <p>\n          <span>\n            22.2.4. Клиенттің шотынан төлемдер сомасын, ұтыстарды немесе\n            бұзушылық нәтижесінде алынған бонустар.\n          </span>\n        </p>\n        <p>\n          <span>\n            22.3. Сіздің пайдаланушы атыңыз бен құпия сөзіңізді қайтарып алуға құқығымыз бар\n            Шарттың кез келген тармағын сақтамаған жағдайда Клиент.\n          </span>\n        </p>\n        <p>\n          <span>23. Зияткерлік меншік объектілеріне құқықтар</span>\n        </p>\n        <p>\n          <span>\n            23.1. Веб-сайттағы барлық мазмұн авторлық құқыққа жатады және\n            Қоғамға тиесілі басқа да мүліктік құқықтар. Барлығын жүктеп алуға болады және\n            веб-сайтта ұсынылған баспа материалдарын жүктеп алуға болады\n            тек бір компьютер үшін. Бұл материалдарды басып шығаруға рұқсат етіледі\n            тек жеке және коммерциялық емес пайдалануға арналған.\n          </span>\n        </p>\n        <p>\n          <span>\n            23.2. Веб-сайтты пайдалану Клиентке ешқандай құқық бермейді\n            Компанияға немесе үшінші тарапқа тиесілі зияткерлік меншік\n            жағы.\n          </span>\n        </p>\n        <p>\n          <span>\n            23.3. Сауда белгісін кез келген пайдалануға немесе қайта шығаруға тыйым салынады.\n            брендтер, сауда белгілері, логотиптер және басқа да жарнамалық материалдар,\n            Компанияның тиісті келісімінсіз веб-сайтта ұсынылған.\n          </span>\n        </p>\n        <p>\n          <span>\n            23.4. Клиент кез келген залал, шығындар немесе шығындар үшін жауапты болады\n            оның тыйым салынған әрекеттерді жасауы нәтижесінде туындаған шығыстар\n            әрекеттер. Клиенттер Компанияға дереу хабарлауы керек\n            олар кез келген тыйым салынған әрекетті жасағаны туралы хабардар болады\n            және тергеуді жүргізуге барлық қажетті көмек көрсету, ол\n            Компания берілген ақпаратты ескере отырып жүзеге асыра алады.\n          </span>\n        </p>\n        <p>\n          <span>24. Клиенттердің жеке деректері</span>\n        </p>\n        <p>\n          <span>\n            24.1. Біз жеке деректерді қорғау талаптарын сақтауға міндеттіміз\n            Компания жиналған жеке ақпаратты пайдаланатын нысан\n            пайдаланушының веб-сайтқа кіруінің нәтижесінде. компаниясымен\n            өңдеу бойынша міндеттемелерді аса байыптылықпен қабылдайды\n            Клиенттеріміздің жеке деректері. Компания өңдейді\n            толық сәйкестікпен Клиенттер ұсынған жеке деректер\n            құпиялылық саясаты.\n          </span>\n        </p>\n        <p>\n          <span>\n            24.2. Жеке деректерді беру арқылы Клиенттер мұнымен келіседі\n            Компанияның жеке деректерді өңдеуге құқығы бар\n            Келісімде көрсетілген мақсаттарға немесе нормативтік және\n            заңды&#160;\n          </span>\n        </p>\n        <p>\n          <span>міндеттемелер.</span>\n        </p>\n        <p>\n          <span>\n            24.3. Құпиялық саясатына сәйкес біз жасамауға міндеттенеміз\n            Клиенттеріміздің жеке деректерін ашпау және бермеу\n            үшінші тұлғаларға, ақпаратты өңдеу жүйелерін қоспағанда және\n            қажет болған жағдайда пайдалана алатын жұмысшылар\n            тек сапалырақ қызмет көрсету мақсатында.\n            24.4. Біз клиенттерден алынған барлық хат-хабарлардың көшірмелерін сақтаймыз,\n            барлық алынған ақпаратты дәл жазу.\n          </span>\n        </p>\n        <p>\n          <span>25. Веб-сайтта cookie файлдарын пайдалану</span>\n        </p>\n        <p>\n          <span>\n            25.1. Біз функционалдылықты қамтамасыз ету үшін cookie файлдарын қолданамыз\n            Веб-сайт. «Cookie» - бұл шағын файлдың арнайы мәтіндік файлы\n            пайдаланушы компьютерінде сақталатын өлшем\n            Веб-сайтқа кіріп, ол арқылы біз нақты тани аламыз\n            пайдаланушылар веб-сайтқа қайта кірген кезде. Қосымша\n            Cookie файлдарын басқару және жою туралы ақпаратты мына веб-сайттан табуға болады:\n            www.aboutcookies.org. Біздің файлдарды жоюды ескеріңіз\n            Cookie файлдары кейбіреулеріне кіруге тыйым салуы мүмкін\n            веб-сайттың бөлімдері мен функциялары.\n          </span>\n        </p>\n        <p>\n          <span>26. Шағымдар мен хабарламалар</span>\n        </p>\n        <p>\n          <span>\n            26.1. Жұмысқа қатысты шағымдар немесе шағымдар туындаған жағдайда\n            Веб-сайт, ең алдымен, өзіңізді жіберуіңіз керек\n            Веб-сайт арқылы онлайн чат арқылы қолдау көрсетуді талап етіңіз\n            Компания (Компанияның тәулік бойы жұмыс істейтін қолдау телефоны 8 (800)\n            301-77-89) немесе компанияның электрондық пошта мекенжайына -\n            support@imbalance.click.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            26.2. Клиент даудың жазбасы сақталғанымен келіседі\n            серверде, қашан дәлел ретінде пайдалануға болады\n            талап арызды қарау.\n          </span>\n        </p>\n        <p>\n          <span>27. Дауларды шешу тәртібі</span>\n        </p>\n        <p>\n          <span>\n            27.1. Ойыншы кез келген жағдайға қарсы тұра алады. Компания жан-жақты және\n            қамтамасыз ету жағдайында барлық даулы мәселелерді объективті түрде қарастырады\n            нақты ақпарат – фактілер мен дәлелдер. Даулы ақпарат, с\n            фактілер мен дәлелдерді қолдану жазбаша түрде қамтамасыз етілуге тиіс\n            Компанияның веб-сайты арқылы онлайн чат арқылы (тел.\n            Қоғамды тәулік бойы қолдау – 8(800)301-77-89) немесе сағ.\n            Компанияның қолдау қызметінің электрондық пошта мекенжайы security@imbalance.click болып табылады. Б\n            шағым немесе сұраныс хатты алған күннен бастап 14 күн ішінде\n            қаралады және нәтижесі туралы Клиентке хабарланады\n            жауап хатында қарастырылады. Қажет болса\n            қосымша тексерулер жүргізілсе, Компания қарау мерзімін ұзартуға құқылы\n            өтініш келіп түскен күннен бастап 30 күнге дейін. Хат мәтінінде\n            Кез келген балағат сөздерді қолдануға тыйым салынады\n            қорлау және жалған деректер.&#160;\n          </span>\n        </p>\n        <p>\n          <span>28. Форс-мажор &#160;</span>\n        </p>\n        <p>\n          <span>\n            28.1. Компания кешіктіру немесе орындамау үшін жауапты емес\n            Шартта көрсетілген міндеттемелер, егер олар болса\n            форс-мажорлық мән-жайлар туындаған\n            табиғи апаттарды, соғыстарды, азаматтық толқуларды түсінуі керек,\n            еңбек даулары, коммуналдық қызметтердегі үзілістер,\n            DDoS шабуылдары немесе Интернеттегі басқа шабуылдар тудыруы мүмкін\n            Website.&#160; жұмысына теріс әсер етеді\n          </span>\n        </p>\n        <p>\n          <span>\n            28.2. Форс-мажорлық мән-жайлар кезеңінде\n            Веб-сайттың қызметі тоқтатылды деп саналады және ұзақтығы\n            Осы кезеңде міндеттемелерді орындауда кейінге қалдыру байқалады.\n            Компания іздеу үшін қолында бар барлық құралдарды пайдалануға міндеттенеді\n            міндеттемелерді толық орындауға мүмкіндік беретін шешімдер\n            Клиенттерге, жағдайлардың соңына дейін\n            форс-мажор.&#160;\n          </span>\n        </p>\n        <p>\n          <span>29. Жауапкершіліктен бас тарту &#160;</span>\n        </p>\n        <p>\n          <span>\n            29.1. Егер біз Клиенттің кез келгенін орындайтынына көз жеткізе алмасақ\n            міндеттемелерді немесе біз өзіміз олардың ешқайсысын пайдалана алмаймыз\n            Біздің құқығымыз бар қорғау құралдары, олай емес\n            осы қорғау құралдарынан бас тарту ретінде түсіндіріледі немесе\n            Клиентті міндеттемелерді орындаудан босатудың себебі ретінде.\n          </span>\n        </p>\n        <p>\n          <span>30. &#160; келісімінің бөлінуі</span>\n        </p>\n        <p>\n          <span>\n            30.1. Шарттың кез келген тармақтары жарамсыз болып қалса,\n            заңсыз немесе заңды күшін жоғалтқан жағдайда, осы ереже\n            толық құрайтын Шарттың қалған бөлігінен ажыратылады\n            заңды күшін сақтайды. Мұндай жағдайларда бұл бөлік\n            жарамсыз деп танылады, жаңартылғанына сәйкес өзгертіледі\n            стандарттар\n          </span>\n        </p>\n        <p>\n          <span>31. Сілтемелер&#160;</span>\n        </p>\n        <p>\n          <span>\n            31.1. Веб-сайтта басқа ресурстарға сілтемелер болуы мүмкін,\n            олар біздің бақылауымыздан тыс. Біз жауапты емеспіз\n            басқа сайттардың мазмұны, олардың иелерінің әрекеттері немесе әрекетсіздігі үшін\n            және үшінші тараптың жарнамасы мен демеушілігінің мазмұны үшін. Гиперсілтемелер\n            басқа сайттарға ақпарат тек ақпараттық мақсатта берілген.\n            мақсаттар. Тұтынушылар оларды өз тәуекелдерімен пайдаланады.&#160;\n          </span>\n        </p>\n        <p>\n          <span>32. &#160; бонустық акциялары</span>\n        </p>\n        <p>\n          <span>\n            32.1. Көтерілген ұтыс тігу (ставка) тек бойынша орнатылады\n            ақшалай бонустар және тек бонус сомасына қолданылады. Егер\n            бонус салымның пайызы болып табылады, содан кейін бәс қолданылады\n            пайыз сомасы. Ұтыс тігу мөлшері орындалатын бонустық науқанға байланысты.\n            және Website.&#160; арқылы орнатылады\n          </span>\n        </p>\n        <p>\n          <span>\n            32.2. Сіз ақшалай бонусты толық болған жағдайда ғана ала аласыз\n            бәс тігу.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            Тіркеу немесе басқа жағдайларда ақшалай бонустарды есептеу кезінде,\n            бонус алған кезде Клиенттен қаражат салу талап етілмейді\n            теңгерім, бонус есептеуді қайтарып алу біріншіге дейін мүмкін емес\n            депозит.\n          </span>\n        </p>\n      </div>\n";
